from __future__ import annotations

from typing import Any

import password_store


def register_password(password: str) -> str:
    """
    Register a new password and return the value to store.

    Uses the organisation's password-storage policy (OWASP Password Storage Cheat Sheet)
    via the application's password_store.hash_new_password API.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a string")
    return password_store.hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against the stored password hash.

    Accepts stored hashes produced by register_password or any previously supported formats.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a string")
    if not isinstance(stored, str):
        raise TypeError("stored must be a string")
    return password_store.verify_password(password, stored)
